    const active = P80TopikExamService.active();
    return `<div class="p80-shell">${header('TOPIK Exam Intelligence', 'Làm đề → phân tích lỗi → luyện đúng điểm yếu → đo lại.','topik')}<section class="section p80-hero"><div><span class="p80-pill">${runtime.config.examCatalog.length} KỲ / BỘ ĐỀ · ${coverage.total} CÂU GỐC</span><h2>Không chỉ làm đề.</h2><p>Mỗi đáp án đều có trạng thái xác minh. Metadata kỳ thi chính thức không được biến thành đề giả.</p></div><div class="p80-cycle"><span>Làm đề</span><i>→</i><span>Phân tích</span><i>→</i><span>Cải thiện</span></div></section>${active ? `<section class="section p80-resume"><div><b>Phiên đang làm: ${escapeHtml(active.title)}</b><small>${Object.keys(active.answers || {}).length}/${active.questions.length} câu đã trả lời</small></div><button class="btn primary" data-p80-resume>Tiếp tục</button></section>` : ''}<section class="section p80-stats"><article><b>${coverage.listening}</b><span>Listening</span></article><article><b>${coverage.reading}</b><span>Reading</span></article><article><b>${coverage.writing}</b><span>Writing</span></article><article><b>${coverage.total}</b><span>Original questions</span></article></section><section class="section p80-grid">${(runtime.config.mockTests || []).map((mock) => `<article class="p80-card"><small>REAL EXAM MODE · ${mock.durationMinutes} PHÚT</small><h2>${escapeHtml(mock.title)}</h2><p>${mock.questionCount} câu tự biên soạn · đáp án xác minh nội bộ · timer · tự nộp</p><button class="btn primary" data-p80-mock="${mock.id}">Bắt đầu Full Test</button></article>`).join('')}<article class="p80-card accent"><small>SMART GENERATOR</small><h2>5 dễ · 10 vừa · 5 khó</h2><p>Ưu tiên level, weak skill và goal của bạn.</p><button class="btn primary" data-view="topik-generator-p80">Tạo đề 20 câu</button></article><article class="p80-card"><small>SCORE PREDICTION</small><h2>TOPIK I: ${ti.attempts ? `${ti.predictedScore}/${ti.maxScore}` : 'Chưa đủ dữ liệu'}</h2><p>TOPIK II: ${tii.attempts ? `${tii.predictedScore}/${tii.maxScore} · readiness ${tii.readinessLevel || '—'}` : 'Chưa đủ dữ liệu'}</p><button class="btn secondary" data-view="topik-report-p80">Mở lịch sử & báo cáo</button></article></section><section class="section p80-actions"><button class="btn secondary" data-view="topik-bank-p80">Kho đề</button><button class="btn secondary" data-view="topik-section-p80">Luyện theo phần</button><button class="btn secondary" data-view="topik-types-p80">Luyện theo dạng</button><button class="btn secondary" data-view="error-notebook">Sổ lỗi</button></section>${notice()}</div>`;
