    return `<div class="p80-shell p80-exam"><section class="section p80-exam-head"><div><small>${escapeHtml(session.title)} · ${titleCase(question.section)} · ${escapeHtml(session.format || 'PBT')}</small><h1>Câu ${session.index + 1}/${session.questions.length}</h1><span class="p80-section-progress">Tiến độ phần ${titleCase(question.section)} · ${sectionAnswered}/${sectionQuestions.length}</span></div><div id="p80ExamTimer" data-deadline="${escapeHtml(session.deadlineAt)}">${Math.floor(remaining / 60)}:${String(remaining % 60).padStart(2, '0')}</div></section><section class="section p80-exam-card"><div class="p80-question-tools"><span class="p80-difficulty ${question.difficulty}">${question.difficulty} · ${titleCase(question.questionType)}</span><button data-p80-mark="${question.id}" class="${isMarked ? 'marked' : ''}">${isMarked ? '★ Đã đánh dấu' : '☆ Đánh dấu'}</button></div><h2>${escapeHtml(question.prompt)}</h2>${question.audioText ? `<button class="p80-audio" data-p80-audio="${escapeHtml(question.audioText)}">🔊 Nghe câu hỏi</button>` : ''}${question.section === 'writing' ? `<textarea id="p80WritingAnswer" rows="10" maxlength="3000" placeholder="Viết câu trả lời bằng tiếng Hàn…">${escapeHtml(answer)}</textarea><small>Chấm luyện tập theo độ dài và từ khóa; không phải điểm viết chính thức.</small>` : `<div class="p80-options">${(question.options || []).map((option, index) => `<button class="${answer === option ? 'selected' : ''}" data-p80-answer="${escapeHtml(option)}"><span>${String.fromCharCode(65 + index)}</span>${escapeHtml(option)}</button>`).join('')}</div>`}</section><nav class="section p80-exam-nav">${session.questions.map((item, index) => `<button class="${index === session.index ? 'current' : ''} ${session.answers[item.id] ? 'answered' : ''} ${(session.marked || []).includes(item.id) ? 'marked' : ''}" data-p80-index="${index}">${index + 1}</button>`).join('')}</nav><section class="section p80-exam-actions"><button class="btn secondary" data-p80-index="${Math.max(0, session.index - 1)}" ${session.index === 0 ? 'disabled' : ''}>← Trước</button><button class="btn secondary" data-p80-index="${Math.min(session.questions.length - 1, session.index + 1)}" ${session.index === session.questions.length - 1 ? 'disabled' : ''}>Tiếp →</button><button class="btn primary" data-p80-submit>Nộp bài</button></section><p class="p80-lock">Exam mode khóa đáp án, giải thích và transcript cho đến khi nộp. Bài tự nộp khi hết giờ và được lưu cục bộ để tiếp tục sau khi tải lại.</p></div>`;
